class GenericDistNamePatterns(object):
    run_time_cell_dist_name = r'(?P<CELL_DIST_NAME>/MRBTS-\d+/RAT-\d+/RUNTIME_VIEW-\d+/' \
                              r'MRBTS_\w+-\d+/(GN|WN|LN|NR)BTS_\w+-\d+/(GN|WN|LN|NR)CELL?_[RL]-{})$'
    re_ru_dist_name = r'(?P<RU_DIST_NAME>/MRBTS-\d+/RAT-\d+/RUNTIME_VIEW-\d+/MRBTS_R-\d+/' \
                      r'EQM_R-\d+/APEQM_R-\d+/RMOD_R-{})'


class EnbDistNamePatterns(GenericDistNamePatterns):
    bts_dist_name = "MRBTS-{}/LNBTS-{}"
    cell_dist_name = "MRBTS-{}/LNBTS-{}/LNCEL-{}"
    default_sync_source = "1pps/ToD from external GNSS receiver"
    x2_link_dist_name = 'MRBTS-{}/LNBTS-{}/LNADJGNB-1'


class GnbDistNamePatterns(GenericDistNamePatterns):
    bts_dist_name = "MRBTS-{}/NRBTS-{}"
    cell_group_dist_name = "MRBTS-{}/NRBTS-{}/NRCELLGRP-{}"
    cell_dist_name = "MRBTS-{}/NRBTS-{}/NRCELL-{}"
    default_sync_source = "1pps/ToD from Sync Hub Master"
    x2_link_dist_name = 'MRBTS-{}/NRBTS-{}/LTEENB-1'
    cell_power_group_name = 'MRBTS-{}/NRBTS-{}/NRPGRP-{}'


class WCDMADistNamePatterns(GenericDistNamePatterns):
    bts_dist_name = "MRBTS-{}/WNBTS-{}"


class GSMDistNamePatterns(GenericDistNamePatterns):
    bts_dist_name = "MRBTS-{}/GNBTS-{}"
    bcf_dist_name = "MRBTS-{}/GNBTS-1/GNBCF-1/GNBCF_R-1"


rat_distname_patterns = {
    'NR': GnbDistNamePatterns,
    'LTE': EnbDistNamePatterns,
    'WCDMA': WCDMADistNamePatterns,
    'GSM': GSMDistNamePatterns
}
